const ActionButton = ({ onClick, icon, color = 'ec-primary' }) => {
    const icons = {
        plus: arrowDownSVG,
        copy: CopyIconSVG,
        trash: TrashIconSVG,
        minus: arrowUpSVG,
    };

    const tooltipContent = {
        plus: 'Expand',
        minus: 'Close',
        copy: 'Duplicate',
        trash: 'Delete',
    };

    return (
        <>
            <button
                type="button"
                onClick={onClick}
                data-tooltip-id="action-tooltip"
                data-tooltip-content={tooltipContent[icon]}
                className={`
                    group relative w-10 h-10 flex items-center justify-center
                    rounded-full bg-transparent border border-ec-table-stock
                    hover:bg-${color} hover:border-${color}
                    transition-all duration-300
                `}
            >
                <span className="text-[#3C3C42] group-hover:text-white transition-colors duration-300">
                    {icons[icon]}
                </span>
            </button>
            <Tooltip id="action-tooltip" className="bg-ec-primary" />
        </>
    );
};

export default ActionButton;